function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  stroke("#e08a72");
  strokeWeight(0.5);

  // Sky
  fill("#f0d9b5");
  noStroke();
  rect(0, 0, width, height / 2);

  // Hills
  fill("#d0a884");
  noStroke();
  rect(0, height / 2, width, height / 2);

  // Horizon
  fill("#b98d6b");
  noStroke();
  rect(0, height, 0, height / 2);

  // Sun
  fill("#e08a72");
  noStroke();
  ellipse(200, 200, 40, 40);

  // Clouds
  fill("#e6e6e6");
  noStroke();
  for (let i = 0; i < 10; i++) {
    const x = random(0, width);
    const y = random(0, height / 2);
    const r = random(10, 40);
    const a = random(0.05, 0.15);
    const b = random(0.2, 0.4);
    brush.fillBleed(b);
    brush.circle(x, y, r);
  }
}
